// =============================================================================
// public/src/shared/api-base.js
// Single place that decides whether an /api/... call goes to Vercel (serverless
// function behind the Vercel CDN, counted as Edge Request + Function invocation)
// or straight to the same handler deployed as a Supabase Edge Function
// (supabase/functions/<name>, generated by scripts/build-edge-functions.mjs).
//
// ROLLOUT: deploy the edge function, test it, then flip its flag to true below.
// Rolling back = flip it back (Vercel routes are still in place).
// Test in production without a release:
//   localStorage.setItem("basmagi_edge_api", "college-quiz,ai-chat")   // or "*"
//   localStorage.removeItem("basmagi_edge_api")
// =============================================================================
import { SUPABASE_URL } from "./public-config.js";

/** path (without query) -> edge function name */
const ROUTES = {
  "/api/colleges": "college-quiz",
  "/api/delete-quiz": "college-quiz",
  "/api/reports": "college-quiz",
  "/api/upload-quiz": "upload-quiz",
  "/api/ai-agent/chat": "ai-chat",
  "/api/ai-agent/usage": "ai-usage",
};

/** Flip to true per function once it is deployed and verified. */
const ENABLED = {
  "college-quiz": false,
  "upload-quiz": false,
  "ai-chat": false,
  "ai-usage": false,
};

function overrides() {
  try {
    const v = localStorage.getItem("basmagi_edge_api");
    return v ? new Set(v.split(",").map((s) => s.trim())) : null;
  } catch (_) {
    return null;
  }
}

export function apiUrl(pathAndQuery) {
  const i = pathAndQuery.search(/[?#]/);
  const p = i === -1 ? pathAndQuery : pathAndQuery.slice(0, i);
  const rest = i === -1 ? "" : pathAndQuery.slice(i);
  const fn = ROUTES[p];
  if (!fn) return pathAndQuery;
  const o = overrides();
  const on = o ? o.has("*") || o.has(fn) : ENABLED[fn];
  return on ? `${SUPABASE_URL}/functions/v1/${fn}${rest}` : pathAndQuery;
}
